import { Order } from './types';

/** An exclusive resume point: the first returned order is strictly after this (createdAt, id) pair. */
export interface CursorPair { createdAt: string; id: string }

function compare(a: Pick<Order, 'createdAt' | 'id'>, b: Pick<Order, 'createdAt' | 'id'>): number {
  if (a.createdAt < b.createdAt) return -1;
  if (a.createdAt > b.createdAt) return 1;
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  /**
   * Returns the tenant's orders sorted ascending by (createdAt, id), lexicographic.
   * If `after` is given, only orders strictly after that pair are returned, so a
   * deleted cursor row still resumes at the right position. Filtering by tenant
   * always happens before the cursor is applied, and neither the input array nor
   * its rows are mutated (filter copies before the in-place sort).
   */
  list(tenant: string, after?: CursorPair): Order[] {
    const filtered = this.rows
      .filter(row => row.tenant === tenant)
      .sort((a, b) => compare(a, b));
    if (after === undefined) return filtered;
    const start = filtered.findIndex(row => compare(row, after) > 0);
    return start === -1 ? [] : filtered.slice(start);
  }
}
